def solve(jobs):
    ordered = sorted(jobs, key=lambda job: (job[1], job[0]))
    chosen = []
    for start, end, reward in ordered:
        conflicts = [
            job for job in chosen
            if job[0] < end and start < job[1]
        ]
        if reward > sum(job[2] for job in conflicts):
            chosen = [
                job for job in chosen
                if job[1] <= start or end <= job[0]
            ]
            chosen.append([start, end, reward])
    return sum(job[2] for job in chosen)

